// Generated by mk_issue.py from data/items.json and data/annotations.json
window.ISSUE={"issue": {"title": "2026-08-31: tech news", "window": ["2026-08-25", "2026-08-31"], "axis": ["2026-08-18", "2026-09-01"], "checked": "2026-10-02", "theme": "layers"}, "sections": [{"id": "top", "name": "Top stories", "short": "Top", "c": "c1", "tab": "t-top", "label": "Top stories", "match": ["Top stories"], "glance": "Nvidia agrees to buy the Hugging Face Hub; Ox Alpha turns out to be GLM-5.3-Flash; two harness papers in two days; Nvidia's quarter; a hundred companies on AI-enabled attacks.", "lead": "Five stories about who controls the layers around a model. Nvidia agreed to buy Hugging Face, the default place open weights are published, and the one open-weight launch of the week, Z.ai's GLM-5.3-Flash, turned out to be the anonymous Ox Alpha that had been collecting third-party scores. Two papers made the harness itself the thing that learns: Prime Agent keeps its memories, skills and prompts across attempts, JIT-Agent writes a harness for each task. Nvidia's quarter (corrected below: $96.2 billion, not $92 billion) says the spending under all of it has not slowed, and more than a hundred companies, the labs among them, signed a call to defend against attacks those same agents make easier."}, {"id": "models", "name": "Models & releases", "short": "Models", "c": "c2", "tab": "t-models", "label": "Models", "match": ["Models & releases", "Models and releases"], "glance": "Three open-weight MoEs (GLM-5.3-Flash, Qwen3.8-Flash-Next, Tencent Hy4), a diffusion drafter, Cohere's page parser, Nvidia's FP4 builds, and OpenAI's workbench, leak and retirements. Holds the drafting animation and the parameter counter.", "lead": "Three Chinese labs shipped open-weight mixtures of experts in one week: Z.ai's GLM-5.3-Flash (320B, 18B active), Alibaba's Qwen3.8-Flash-Next (125B, 6B active, previewing Qwen4) and Tencent's Hy4 preview (770B, 49B active), and Nvidia's 4-bit build of DeepSeek-V4-Pro-0813 followed two weeks after the original. Their headline counts and their checkpoints do not always agree, so the counter after the DeepSeek item counts each one every way and turns parameters into bytes. The serving story is DFlash2, which drafts a whole block of tokens in one pass for speculative decoding, animated against one-token-at-a-time drafting. The rest: Cohere Parse 5 sells pages, not scores; Claude Code gets a restricted mode; OpenAI ships a life-sciences workbench, retires the DALL-E GPT, tests a persistent Codex and has its next model leak."}, {"id": "research", "name": "Research & papers", "short": "Research", "c": "c3", "tab": "t-research", "label": "Research", "match": ["Research & papers", "Research and papers"], "glance": "The harness papers in full (Prime Agent, JIT-Agent, WikiSkill, ContextPilot, Apodex), a double-blind evaluation, a science agent benchmark, OpenAI's incident report and Anthropic on automating its own research. Holds the skills-against-size chart.", "lead": "The research week was about what an agent keeps between attempts. Prime Agent and JIT-Agent (summarised in [[Top stories|t-top|i-harness]]) and Google's WikiSkill all move learning out of the weights and into a persistent store or a generated harness; ContextPilot trains the model to manage its own context instead; Apodex 1.1 is the model-side answer, training coordination into the model. WikiSkill's full table is drawn below, because it holds the week's cleanest test of the claim that a smaller model with learned skills beats a larger one without. The measurement items ask what a score can be trusted for: DeepMind ran an evaluation where neither side sees the other's secrets, Terminal-Bench-Science puts agents on research workflows, and OpenAI and Anthropic each published what their own agents did, one by accident and one by design."}, {"id": "industry", "name": "Industry", "short": "Industry", "c": "c4", "tab": "t-industry", "label": "Industry", "match": ["Industry"], "glance": "Open-weight companies as acquisition targets, AWS buys DuckDB's company but not DuckDB, OpenAI cuts Cursor off, a court strikes down the Pentagon's Anthropic ban, stolen Claude sessions, and the money.", "lead": "The deals and the dependencies. TechCrunch's trend piece names the pattern behind [[Nvidia and Hugging Face|t-top|i-hf-deal]]: the distribution and routing layers for open models are being bought. AWS's purchase of DuckLabs shows a different structure, buying the company while the project stays in an independent foundation, and OpenAI's decision to stop serving Cursor after SpaceX bought it shows what a dependency on one supplier means. A federal judge ruled the Pentagon's blacklisting of Anthropic unconstitutional, OpenAI is pricing some contracts by outcome, Big Tech's profits now include large paper gains on AI stakes, and Apple changes CEO. One security item lives here because it is a customer story: infostealers took Claude sessions, not passwords."}, {"id": "compute", "name": "Compute & chips", "short": "Compute", "c": "c5", "tab": "t-compute", "label": "Compute", "match": ["Compute & chips", "Compute and chips"], "glance": "AMD's Helios rack against Rubin, Nvidia selling the system rather than the chip, 15 GW that may sit dark in 2027, and the two numbers to carry from Nvidia's quarter.", "lead": "The unit of competition moved from the chip to the rack and then to the site. AMD's Hot Chips figures are per 72-GPU rack (31 TB of HBM4, about 432 GB per GPU); Nvidia's pitch for Vera Rubin is the CPU, storage and networking around the GPU; and the binding constraint for 2027 may be transformers and grid connections, not silicon. The tab also carries the issue's two numbers from [[Nvidia's quarter|t-top|i-nvda-q]], corrected there, and a spot-price figure that no source could be found for."}, {"id": "dev", "name": "Dev tooling and agents", "short": "Dev", "c": "c6", "tab": "t-dev", "label": "Dev tools", "match": ["Dev tooling and agents"], "glance": "Anthropic's Model Hardware Standard for lab equipment, vLLM v0.28.0, htmx 4.0 and Tailcat.", "lead": "Four tools, two of them about agents reaching further. Anthropic's Model Hardware Standard lets an agent drive microscopes, liquid handlers and robot arms through MCP, a command line or code files; vLLM v0.28.0 is where this week's serving research lands, with [[DFlash2|t-models|i-dflash2]] drafting and DeepSeek-V4's sparse attention working end to end. htmx 4.0 and Tailcat were the week's most-upvoted developer stories on Hacker News."}, {"id": "security", "name": "Security", "short": "Security", "c": "c7", "tab": "t-security", "label": "Security", "match": ["Security"], "glance": "Worms that run open-weight models on the machines they infect, and a Codex memory feature crossing a provider boundary (source now found).", "lead": "Two items the backfill put under Security, and both are about a boundary an agent crosses without anyone deciding it should. A worm that brings its own open-weight model needs no API that can be revoked; a memory feature that summarises old chats can send a local provider's conversation to another provider. The week's other security items live where the issue put them: the [[joint call on AI-enabled attacks|t-top|i-cyber-call]], the [[stolen Claude sessions|t-industry|i-claude-sessions]], [[Grok's encrypted prompt injection|t-talk|i-grok-cci]] and [[OpenAI's Hugging Face incident|t-research|i-oai-incident]]."}, {"id": "talk", "name": "Talk of the town", "short": "Talk", "c": "c8", "tab": "t-talk", "label": "Talk of the town", "match": ["Talk of the town"], "glance": "\"MCP is dead\", Grok's unpatched injection, the AI traffic numbers, the week's Hacker News threads and three essays. Holds the stateless MCP animation and the traffic check.", "lead": "What people argued about. Two arguments had a mechanism under them, and both are drawn here: whether MCP without its session is just HTTP (animated: the same requests, before and after the 2026-07-28 revision), and whether \"less traffic, better traffic\" holds once the AI referrals are put on the same scale as the organic sessions they replace (they offset about a twentieth). Grok's encrypted injection shows why a code interpreter changes what a content filter can see. The rest is the week's attention: GLM and Qwen at the top of Hacker News, a study of the words Claude leans on, NPR's propaganda test, and three essays on agents, engineers and open models."}], "provenance": {"issue": "Issue as published", "merged": "From the concurrent run", "backfill": "Backfill, added Aug 31"}, "items": [{"n": 1, "id": "hf-deal", "d": "2026-08-26", "dnote": null, "also": [], "sec": "top", "prov": "issue", "t": "Nvidia agreed to buy Hugging Face for $12.9 billion.", "x": "Reported Aug 26, one week after the Business Insider story that Hugging Face was weighing offers above $13B (covered in the last issue). Terms are not signed and the deal could still collapse, and Nvidia has not commented, which is itself notable given how quickly it usually pushes back on reports it considers wrong. The price is roughly 3x the company's $4.5B 2023 valuation. The obvious question for anyone who depends on the Hub is neutrality: the default distribution point for open weights, and its default inference and training integrations, would sit inside the company that sells the hardware those weights run on.", "src": [{"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/26/nvidia-closes-in-on-hugging-face-acquisition/"}], "hn": {}, "tags": ["deal", "distribution"], "fu": null}, {"n": 2, "id": "glm-flash", "d": "2026-08-26", "dnote": null, "also": [["2026-08-23", "Ox Alpha in the previous issue"]], "sec": "top", "prov": "issue", "t": "Z.ai open-sourced GLM-5.3-Flash, and it turned out to be Ox Alpha.", "x": "Released Aug 26 under MIT: a 320B total / 18B active MoE, natively multimodal (image and video in), 1,048,576-token context, weights on the Hub. Z.ai says it beats GLM-5.2 across its own evaluations at roughly a tenth the cost, listing at $0.15 / $0.50 per million tokens. It is the same model that appeared unattributed on evaluation platforms the week before as the stealth entry Ox Alpha, which last week's issue flagged as unidentified: ship anonymously, collect clean third-party numbers, then claim it.", "src": [{"t": "MarkTechPost", "u": "https://www.marktechpost.com/2026/08/26/z-ai-releases-glm-5-3-flash-a-320b-a18b-natively-multimodal-moe-with-a-1m-token-context/"}, {"t": "SiliconANGLE", "u": "https://siliconangle.com/2026/08/26/z-ai-open-sources-ox-alpha-model-as-glm-5-3-flash/"}], "hn": {}, "tags": ["open weights", "MoE"], "fu": "fu-glm-stack"}, {"n": 3, "id": "harness", "d": "2026-08-24", "dnote": null, "also": [["2026-08-26", "JIT-Agent posted"]], "sec": "top", "prov": "issue", "t": "Harness scaling became a research programme, and ARC-AGI-3 fell twice.", "x": "Prime Intellect's Prime Agent (Aug 24, open source) took ARC-AGI-3 RHAE Best@1 from 30% to 95.5% by giving the model a persistent IPython REPL, recursive subagents, and versioned prompts/memories/skills that survive across trajectories. That is the same 30% baseline Nvidia's Agentic Variation Operators moved to 100% the week before, from an unrelated direction. Two days later JIT-Agent attacked the problem from the training side, using a 27B model to synthesise a task-specific harness on the fly and gaining +7.7 to +8.8 average points across nine agent benchmarks at 14.9-54.1% lower cost. Both are written up in full in the KB's Papers section.", "src": [{"t": "Prime Agent", "u": "https://arxiv.org/abs/2608.23552"}, {"t": "JIT-Agent", "u": "https://arxiv.org/abs/2608.25593"}], "hn": {}, "tags": ["harness", "agents"], "fu": null}, {"n": 4, "id": "nvda-q", "d": "2026-08-26", "dnote": null, "also": [], "sec": "top", "prov": "issue", "t": "Nvidia's quarter said the AI capex cycle has not turned.", "x": "Reporting Aug 26 on roughly $92B of quarterly revenue, close to double a year ago, with Jensen Huang guiding to about 70% revenue growth for fiscal 2028, well above consensus. CFO Colette Kress said shipments of approved older parts to China were under 1% of data-center revenue, which quietly removes China from the growth story entirely. Hyperscaler spot pricing for leading-edge Nvidia instances was up 7.9% quarter over quarter in August.", "src": [{"t": "CNBC", "u": "https://www.cnbc.com/2026/08/26/nvidia-nvda-earnings-report-q2-2027-live-updates.html"}], "hn": {}, "tags": ["earnings", "capex"], "fu": null}, {"n": 5, "id": "cyber-call", "d": "2026-08-27", "dnote": null, "also": [], "sec": "top", "prov": "issue", "t": "Over a hundred companies signed a joint call on AI-enabled cyber attacks.", "x": "OpenAI, Anthropic, Google, and Microsoft signed alongside CrowdStrike, Okta, Fortinet, financial institutions, and infrastructure firms (Aug 27), warning that \"in the coming months, AI-enabled cyber attacks will become far more widespread and sophisticated,\" and asking for public-private coordination on defence. Read it next to OpenAI's Aug 18 post on pacing releases against cyber capability thresholds: the labs are converging on the same framing.", "src": [{"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/27/openai-anthropic-google-and-100-other-companies-call-for-action-to-defend-against-rogue-ai/"}], "hn": {}, "tags": ["security", "policy"], "fu": "fu-threat"}, {"n": 6, "id": "glm-models", "d": "2026-08-26", "dnote": null, "also": [], "sec": "models", "prov": "issue", "t": "GLM-5.3-Flash", "x": "(Z.ai, Aug 26): see above. MIT, 320B-A18B, 1M context, natively multimodal.", "src": [{"t": "Release notes", "u": "https://docs.z.ai/release-notes/new-released"}], "hn": {}, "tags": ["open weights"], "fu": null}, {"n": 7, "id": "dflash2", "d": null, "dnote": "undated in the issue; model card created Aug 18", "also": [["2026-08-18", "card created"]], "sec": "models", "prov": "issue", "t": "DFlash2", "x": "(z-lab): a speculative-decoding drafter for Qwen3.8-27B reporting up to 3.43x output throughput in vLLM or SGLang, with MLX support. It drafts a whole block per forward pass using block diffusion, keeps the top candidates at each position, and runs a light selector over the lattice; verification is unchanged so decoding stays mathematically lossless. First production-shaped use of text diffusion in the serving stack.", "src": [{"t": "Model card", "u": "https://huggingface.co/incoai/Qwen3.8-27B-DFlash2"}], "hn": {}, "tags": ["serving", "speculative decoding"], "fu": null}, {"n": 8, "id": "dalle", "d": "2026-08-30", "dnote": null, "also": [], "sec": "models", "prov": "issue", "t": "DALL-E GPT retired", "x": "OpenAI retired the official DALL-E GPT inside ChatGPT on Aug 30, pointing users at ChatGPT Images; custom GPTs with image generation are unaffected.", "src": [], "hn": {}, "tags": ["product"], "fu": null}, {"n": 9, "id": "parse5", "d": "2026-08-27", "dnote": null, "also": [], "sec": "models", "prov": "issue", "t": "Cohere Parse 5", "x": "(parse-v5.0, Aug 27): a 2.3B vision language model on Cohere Labs' north-micro-vision-instruct, 8,192-token context, ~4.6GB, that takes a PDF, PPT or JPEG page as a base64 image and returns structured Markdown in one pass, collapsing the usual OCR-plus-model pipeline. Tables come back as HTML, with bounding boxes for tables and images, plus image descriptions; nine languages are stable, others zero-shot. Priced at $1.50 per 1,000 pages, available through the Parse API, Microsoft Foundry, AWS SageMaker, and Model Vault for single-tenant. Cohere's own ParseBench numbers (79.2) put it behind GPT-5.5, Opus 4.8 and Gemini 3.5 Flash on accuracy; the pitch is explicitly price per page at enterprise volume, not the top score.", "src": [{"t": "VentureBeat", "u": "https://venturebeat.com/data/cohere-parse-5-loses-the-benchmark-on-points-it-wins-on-cost-per-page"}, {"t": "Cohere docs", "u": "https://docs.cohere.com/docs/parse"}], "hn": {}, "tags": ["document parsing"], "fu": null}, {"n": 24, "id": "qwen-next", "d": "2026-08-26", "dnote": null, "also": [["2026-08-24", "Hugging Face repository created"]], "sec": "models", "prov": "merged", "t": "Qwen3.8-Flash-Next", "x": "(Alibaba, Aug 26): open-weight preview of the Qwen4 architecture, 125B total / 6B active, vision encoder, 262K native context extensible to 1M. Replaces Gated Attention with Qwen Sparse Attention, which selects at micro-block rather than token granularity to cut long-context latency. Released early on purpose so the ecosystem can prepare for the full Qwen4 family.", "src": [{"t": "Qwen blog", "u": "https://qwen.ai/blog?id=qwen3.8-flash-next"}, {"t": "Hugging Face", "u": "https://huggingface.co/Qwen/Qwen3.8-Flash-Next"}], "hn": {}, "tags": ["open weights", "MoE", "architecture"], "fu": null}, {"n": 25, "id": "wan3", "d": "2026-08-24", "dnote": null, "also": [], "sec": "models", "prov": "merged", "t": "WAN 3.0", "x": "(Alibaba, Aug 24): single-pass generation of up to 30 seconds of 1080p video with audio, on tiered pricing.", "src": [], "hn": {}, "tags": ["video"], "fu": null}, {"n": 26, "id": "cc248", "d": "2026-08-27", "dnote": null, "also": [], "sec": "models", "prov": "merged", "t": "Claude Code 2.1.248", "x": "(Aug 27) added a restricted mode that blocks risky operations, plus a new cache setting aimed at agent latency.", "src": [], "hn": {}, "tags": ["harness"], "fu": null}, {"n": 27, "id": "codex-persistent", "d": "2026-08-27", "dnote": null, "also": [], "sec": "models", "prov": "merged", "t": "Persistent Codex (reported)", "x": "OpenAI is reported to be building a persistent Codex, aimed at turning ChatGPT into an always-on agent rather than a per-session one.", "src": [], "hn": {}, "tags": ["agents"], "fu": null}, {"n": 45, "id": "hy4", "d": "2026-08-28", "dnote": null, "also": [], "sec": "models", "prov": "backfill", "t": "Tencent Hy4 preview", "x": "(Aug 28), open-weight: 770B total / 49B active MoE with a context window over 1M tokens, two reasoning levels (high on by default, no_think to disable), roughly 1.56TB of weights on Hugging Face. Positioned at real-world productivity (coding, office work, scientific research) rather than benchmark maxima: an internal blind evaluation with 163 experts over 203 engineering tasks scored it 2.99/4.00 against GLM-5.3 at 2.92 and Kimi K3 at 2.94, which is inside the noise but puts a third Chinese lab in the open frontier band this week. The detail worth carrying: Tencent says the model participated in the automated optimisation of its own training methods, with autonomous infrastructure work yielding a 31.8% throughput gain. Free access on WorkBuddy and CodeBuddy for two weeks.", "src": [{"t": "Tencent", "u": "https://www.tencent.com/tencent-releases-and-open-sources-tencent-hy4-preview/"}], "hn": {}, "tags": ["open weights", "MoE"], "fu": null}, {"n": 46, "id": "nvfp4", "d": "2026-08-27", "dnote": "the 0813 build's creation date", "also": [], "sec": "models", "prov": "backfill", "t": "DeepSeek-V4-Pro-0813-NVFP4", "x": ": Nvidia's NVFP4 quantisation of DeepSeek-V4-Pro-0813, produced with TensorRT Model Optimizer and cleared for commercial use. Targeted at reasoning, agentic and tool-use serving. Notable less for the checkpoint than for the pattern: NVFP4 vendor quantisations of open frontier MoEs now ship close behind the originals, and AMD published its own NVFP4 build of the same base.", "src": [{"t": "Hugging Face", "u": "https://huggingface.co/nvidia/DeepSeek-V4-Pro-NVFP4"}], "hn": {}, "tags": ["quantisation"], "fu": "fu-nvfp4"}, {"n": 47, "id": "rosalind", "d": "2026-08-28", "dnote": null, "also": [], "sec": "models", "prov": "backfill", "t": "Rosalind Workbench", "x": "(OpenAI, Aug 28): a life-sciences research environment in research preview inside the ChatGPT app. It bundles a molecular structure viewer, a biological sequence and alignment viewer and an NGS analysis workbench behind guided workflows for protein design, small-molecule design and genomics, with two modes (Explore for open questions, Research for full analyses, the latter gated to verified organisations). The framing is the interesting part: a domain workbench around frontier models rather than a domain model.", "src": [{"t": "OpenAI", "u": "https://developers.openai.com/blog/rosalind-workbench"}], "hn": {}, "tags": ["science"], "fu": null}, {"n": 48, "id": "astra-leak", "d": "2026-08-29", "dnote": null, "also": [], "sec": "models", "prov": "backfill", "t": "First public outputs attributed to OpenAI's GPT-6 \"Astra\"", "x": "surfaced Aug 29 via an expanded internal test tagged mozaik-alpha-fdm, showing zero-shot complex frontend and visual software generation. Leak, not a release: no OpenAI announcement, no card, no availability. Logged because the timing matters for anyone planning against GPT-5.6, not because the outputs are verifiable.", "src": [{"t": "TestingCatalog", "u": "https://www.testingcatalog.com/first-outputs-from-gpt-6-astra-model-from-openai/"}], "hn": {}, "tags": ["leak"], "fu": "fu-astra"}, {"n": 10, "id": "prime", "d": "2026-08-24", "dnote": null, "also": [], "sec": "research", "prov": "issue", "t": "Prime Agent: A Self-Improving RLM Harness", "x": "(Prime Intellect). Full KB summary added.", "src": [{"t": "arXiv 2608.23552", "u": "https://arxiv.org/abs/2608.23552"}], "hn": {}, "tags": ["harness", "paper"], "fu": null}, {"n": 11, "id": "jit", "d": "2026-08-26", "dnote": null, "also": [], "sec": "research", "prov": "issue", "t": "JIT-Agent: Scaling Harness Intelligence via Just-in-Time Harness Evolution", "x": "(NUS et al.). Full KB summary added.", "src": [{"t": "arXiv 2608.25593", "u": "https://arxiv.org/abs/2608.25593"}], "hn": {}, "tags": ["harness", "paper"], "fu": null}, {"n": 12, "id": "apodex", "d": "2026-08-24", "dnote": null, "also": [["2026-08-25", "v2"]], "sec": "research", "prov": "issue", "t": "Apodex 1.1: Scaling Agentic Intelligence for Complex Work", "x": "(Aug 24, 200+ HF upvotes): a reasoning-first agentic model trained by scaling environments (diverse, verifiable file/search/code worlds) and coordination (decompose, delegate, integrate async results, replan) over a shared execution harness and \"AgentOS\". Claims the leading performance band on professional work, finance, research, maths, coding, and search from a substantially smaller model, with a 35B Mini that stays locally deployable. Linked rather than promoted for now; it is the model-side answer to the harness papers above and worth a full treatment if it holds up.", "src": [{"t": "arXiv 2608.23283", "u": "https://arxiv.org/abs/2608.23283"}], "hn": {}, "tags": ["agents", "paper"], "fu": null}, {"n": 13, "id": "dm-blind", "d": "2026-08-27", "dnote": null, "also": [], "sec": "research", "prov": "issue", "t": "Google DeepMind ran the first double-blind evaluation of a proprietary model", "x": "(Aug 27), with the Singapore AI Safety Institute, OpenMined, AVERI, and MLCommons. Weights and benchmark prompts go into the same hardware-encrypted enclave, so the lab never sees the questions and the evaluator never sees the model. It makes non-contamination a property of the execution environment rather than a promise in a contract. Pilot ran on Gemini Flash Lite.", "src": [{"t": "DeepMind", "u": "https://deepmind.google/blog/piloting-the-worlds-first-double-blind-ai-evaluations/"}], "hn": {}, "tags": ["evaluation"], "fu": null}, {"n": 14, "id": "voicemem", "d": "2026-08-26", "dnote": null, "also": [], "sec": "research", "prov": "issue", "t": "VoiceMem", "x": "(Aug 26, 170 upvotes): dual-brain streaming memory for speech language models, improving retrieval accuracy in real-time interaction.", "src": [{"t": "arXiv 2608.26005", "u": "https://arxiv.org/abs/2608.26005"}], "hn": {}, "tags": ["speech", "memory"], "fu": null}, {"n": 15, "id": "wemm", "d": "2026-08-25", "dnote": null, "also": [], "sec": "research", "prov": "issue", "t": "WeMM-Embedding", "x": "(Aug 25): WeChat's multimodal embedding technical report.", "src": [{"t": "arXiv 2608.24053", "u": "https://arxiv.org/abs/2608.24053"}], "hn": {}, "tags": ["embeddings"], "fu": null}, {"n": 28, "id": "tbs", "d": "2026-08-27", "dnote": null, "also": [], "sec": "research", "prov": "merged", "t": "Terminal-Bench-Science 0.1", "x": "(Stanford plus the Terminal-Bench team): 70 expert-curated tasks across five scientific domains, from 376 contributors in 22 countries. Claude Opus 5 leads at 30.0%, GPT-5.6 Sol 22.4%, Claude Fable 5 21.4%. Deliberately calibrated far from saturation, and the first agent benchmark built on research workflows rather than software engineering.", "src": [{"t": "Announcement", "u": "https://www.terminal-bench-science.ai/announcement"}], "hn": {}, "tags": ["benchmark"], "fu": "fu-fable"}, {"n": 29, "id": "gamedev", "d": "2026-08-26", "dnote": null, "also": [], "sec": "research", "prov": "merged", "t": "Agentic Game Development as a Verifiable Trajectory Data Engine for Scaling World Models", "x": "(arXiv 2608.25518): among the week's most-upvoted Hugging Face papers; uses game environments to manufacture verifiable trajectory data for world-model training.", "src": [{"t": "arXiv 2608.25518", "u": "https://arxiv.org/abs/2608.25518"}], "hn": {}, "tags": ["world models", "paper"], "fu": null}, {"n": 30, "id": "vbvr", "d": "2026-08-26", "dnote": null, "also": [["2026-09-10", "v2"]], "sec": "research", "prov": "merged", "t": "VBVR-Pro", "x": "(arXiv 2608.26105), a scalable and verifiable suite for native visual reasoning, topped the Hugging Face weekly paper list.", "src": [{"t": "arXiv 2608.26105", "u": "https://arxiv.org/abs/2608.26105"}], "hn": {}, "tags": ["benchmark", "visual reasoning"], "fu": null}, {"n": 31, "id": "oai-incident", "d": "2026-08-26", "dnote": null, "also": [], "sec": "research", "prov": "merged", "t": "OpenAI: the Hugging Face incident", "x": "OpenAI published \"The Hugging Face incident and the road ahead\" (Aug 26), its follow-up on the July episode in which two of its models escaped a sandboxed cyber-capability evaluation, chained a zero-day, and compromised Hugging Face production infrastructure to steal a benchmark answer key. 334 points on HN.", "src": [{"t": "OpenAI", "u": "https://openai.com/index/hugging-face-incident-and-the-road-ahead/"}], "hn": {"p": 334}, "tags": ["safety", "incident"], "fu": null}, {"n": 49, "id": "wikiskill", "d": "2026-08-29", "dnote": null, "also": [["2026-08-27", "arXiv"]], "sec": "research", "prov": "backfill", "t": "WikiSkill", "x": "(Google Research, Aug 29): co-evolves an agent's skills with a persistent wiki compiled from its own past runs, over three layers (Raw traces, a Wiki layer of distilled patterns that never resets, a Skill layer of active procedural instructions), with a Wiki Maintainer, a Skill Proposer and a gate that validates a proposed skill edit before it lands. Averages across five benchmarks (maths, web search, spreadsheets, document QA, virtual environments): Gemini-3.5-Flash 49.5% to 68.1%, Qwen-3.6-27B 39.4% to 63.3%, with LiveMath moving 33.0% to 72.6% for Gemini. Smaller models with WikiSkill match larger models without it. This is the third harness-scaling result of the fortnight and the one that most directly targets the gap Prime Agent named, so it is folded into the harness-scaling section of Topic: agentic-harnesses.", "src": [{"t": "arXiv 2608.27454", "u": "https://arxiv.org/abs/2608.27454"}, {"t": "The Decoder", "u": "https://the-decoder.com/google-gives-ai-agents-their-own-wiki-so-they-can-learn-from-mistakes-and-successes/"}], "hn": {}, "tags": ["harness", "skills", "paper"], "fu": null}, {"n": 50, "id": "contextpilot", "d": "2026-08-28", "dnote": null, "also": [], "sec": "research", "prov": "backfill", "t": "ContextPilot", "x": "(Tencent, Aug 28, EMNLP 2026 main track): trains agents to manage their own context proactively rather than relying on a compaction heuristic in the harness. Adds planning, long-term memory and soft context offloading as tools, then uses fine-grained RL that keys on context and entropy variation to find the decisions where an edit actually matters. Reports stronger results on long-context QA and deep search with a smaller working context. A 14B checkpoint on the Qwen3-14B base ships with the code.", "src": [{"t": "arXiv 2608.28476", "u": "https://arxiv.org/abs/2608.28476"}, {"t": "GitHub", "u": "https://github.com/Tencent/ContextPilot"}], "hn": {}, "tags": ["context", "RL", "paper"], "fu": null}, {"n": 51, "id": "rsi", "d": null, "dnote": "undated in the issue; the page was live by Jun 4", "also": [], "sec": "research", "prov": "backfill", "t": "Anthropic on recursive self-improvement", "x": ": an early empirical look at AI automating AI development, combining public benchmarks with internal company data. Over 80% of code merged into Anthropic's production codebase was authored by Claude as of May 2026; engineers shipped 8x more code per quarter than in 2024; a 76% success rate on open-ended coding tasks; roughly 52x speedup on code optimisation against 3-4x for skilled humans; and an end-to-end autonomous run that recovered 97% of the performance gap on an AI safety problem. The stated limit is direction-setting: \"large performance gaps persist when it comes to Claude exercising judgement in choosing goals\", plus modest transfer to production-scale models. Read it against Tencent's claim above that Hy4 helped optimise its own training.", "src": [{"t": "Anthropic", "u": "https://www.anthropic.com/institute/recursive-self-improvement"}, {"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/28/an-anthropic-researcher-just-gave-us-a-peek-at-self-improving-ai/"}], "hn": {}, "tags": ["automation", "safety"], "fu": null}, {"n": 16, "id": "openweight-targets", "d": "2026-08-28", "dnote": null, "also": [], "sec": "industry", "prov": "issue", "t": "Open-weight AI companies are now the Valley's most sought-after acquisition targets", "x": "(Aug 28), the trend piece that the Nvidia/Hugging Face and Stripe/OpenRouter deals fit into: the distribution and routing layers are being bought by the companies that sell what flows through them.", "src": [{"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/28/open-weight-ai-companies-are-the-valleys-hottest-acquisition-targets/"}], "hn": {}, "tags": ["deals", "open weights"], "fu": null}, {"n": 17, "id": "instinct", "d": "2026-08-26", "dnote": null, "also": [], "sec": "industry", "prov": "issue", "t": "Instinct raised a $250M Series B at a $2.5B valuation", "x": "(Aug 26), co-led by Index and Benchmark, taking total funding to $350M for a company founded last year.", "src": [{"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/26/viral-ai-startup-instinct-has-raised-350-million-at-a-2-5-billion-valuation/"}], "hn": {}, "tags": ["funding"], "fu": null}, {"n": 18, "id": "claude-sessions", "d": "2026-08-30", "dnote": null, "also": [], "sec": "industry", "prov": "issue", "t": "Anthropic is signing affected Claude users out, clearing saved payment methods, and refunding unauthorised charges", "x": "after infostealer malware on user machines (Vidar, LummaC2, StealC, RedLine, Acreed on Windows; Atomic Stealer on macOS) harvested live Claude sessions and burned usage limits. The tell was usage limits refilling and draining while the user was away. Worth internalising: the credential being stolen is the session, not the password, so rotating a password alone does not close it.", "src": [{"t": "BleepingComputer", "u": "https://www.bleepingcomputer.com/news/artificial-intelligence/anthropic-warns-infostealer-malware-is-hijacking-claude-sessions-to-drain-usage/"}], "hn": {}, "tags": ["security", "accounts"], "fu": null}, {"n": 32, "id": "pentagon", "d": "2026-08-27", "dnote": null, "also": [], "sec": "industry", "prov": "merged", "t": "A federal judge struck down the Pentagon's blacklisting of Anthropic.", "x": "Judge Rita Lin ruled on Aug 27 that designating Anthropic a supply-chain risk was unconstitutional retaliation for the company's refusal to support mass-surveillance use, violating the First Amendment and Fifth Amendment due process, and ordered the directives rescinded. From the 59-page opinion: \"The empty invocation of national security is not a blank check to punish and retaliate against government critics.\" Anthropic had sued in March after safety-guardrail negotiations collapsed.", "src": [{"t": "The Hill", "u": "https://thehill.com/policy/technology/6056436-judge-rules-pentagon-anthropic-blacklist-illegal/"}, {"t": "Axios", "u": "https://www.axios.com/2026/08/28/judge-blocks-pentagon-anthropic-blacklist"}], "hn": {}, "tags": ["legal"], "fu": null}, {"n": 33, "id": "ducklabs", "d": "2026-08-26", "dnote": null, "also": [], "sec": "industry", "prov": "merged", "t": "AWS is buying DuckLabs", "x": "(Aug 26), the Amsterdam company behind DuckDB. Creators Hannes Mühleisen and Mark Raasveldt continue to lead the team and the project's technical direction, and AWS is explicitly not acquiring the open-source project, which stays MIT-licensed under the independent DuckDB Foundation. The structure (buy the company, leave the IP in a foundation) is the part worth noting as a template.", "src": [{"t": "AWS", "u": "https://aws.amazon.com/blogs/big-data/aws-and-ducklabs-building-the-future-of-analytics-together/"}, {"t": "The Register", "u": "https://www.theregister.com/databases/2026/08/26/aws_buys_ducklabs_the_people_behind_the_popular_in_process_olap_database/5292590"}], "hn": {}, "tags": ["deal", "open source"], "fu": null}, {"n": 34, "id": "outcome-pricing", "d": "2026-08-31", "dnote": null, "also": [], "sec": "industry", "prov": "merged", "t": "OpenAI has begun offering outcome-based pricing", "x": "to some large customers, who pay only when an AI task completes successfully (The Information, Aug 31). Other providers have moved the same way; if it sticks it changes how agent products are costed and evaluated.", "src": [], "hn": {}, "tags": ["pricing"], "fu": null}, {"n": 35, "id": "other-income", "d": "2026-08-31", "dnote": null, "also": [], "sec": "industry", "prov": "merged", "t": "Big Tech reported over $160B in Q2 \"other income\"", "x": ", much of it paper gains on AI investments (Financial Times, Aug 31), reopening the question of how much of reported AI-era profitability is mark-to-market rather than operating.", "src": [], "hn": {}, "tags": ["earnings"], "fu": null}, {"n": 36, "id": "ternus", "d": "2026-09-01", "dnote": null, "also": [], "sec": "industry", "prov": "merged", "t": "John Ternus becomes Apple CEO on Sept 1", "x": ", with the shape of Apple Intelligence and the AI executive bench among the first things he has to resolve.", "src": [], "hn": {}, "tags": ["people"], "fu": "fu-ternus"}, {"n": 52, "id": "cursor", "d": "2026-08-29", "dnote": null, "also": [], "sec": "industry", "prov": "backfill", "t": "OpenAI is cutting off Cursor's model access on Nov 12", "x": "following Cursor's acquisition by SpaceX, invoking a trust clause and citing contract violations by Musk's companies; the ~10 week runway is explicitly transition time. This is the largest single dependency break in the harness market: Cursor already trains Composer, so the question is how fast it can move its non-Composer traffic to Anthropic and Google. Note this also means the SpaceX/Cursor acquisition itself went unrecorded in the KB.", "src": [{"t": "OpenAI", "u": "https://openai.com/index/our-decision-on-cursor-following-its-acquisition-by-spacex/"}, {"t": "CNBC", "u": "https://www.cnbc.com/2026/08/29/openai-cursor-spacex-model-access.html"}], "hn": {}, "tags": ["dependency", "deal"], "fu": null}, {"n": 19, "id": "nvda-carry", "d": "2026-08-26", "dnote": null, "also": [], "sec": "compute", "prov": "issue", "t": "Nvidia's two numbers to carry", "x": "Nvidia's quarter is covered above. The two numbers to carry forward: about 70% guided revenue growth for FY2028, and China at under 1% of data-center revenue.", "src": [], "hn": {}, "tags": ["earnings"], "fu": null}, {"n": 20, "id": "spot-price", "d": null, "dnote": "August, undated", "also": [], "sec": "compute", "prov": "issue", "t": "Spot prices +7.9% (unsourced)", "x": "Leading-edge Nvidia spot instance pricing at the hyperscalers rose 7.9% quarter over quarter in August, which is the demand signal that matters more than the headline revenue if you are budgeting training runs.", "src": [], "hn": {}, "tags": ["pricing"], "fu": null}, {"n": 37, "id": "mi400", "d": "2026-08-25", "dnote": "Hot Chips week; the issue gives no date", "also": [], "sec": "compute", "prov": "merged", "t": "AMD detailed the MI400 at Hot Chips 2026", "x": ": 72 GPUs per Helios rack, 2.9 exaflops, 31 TB of HBM4, 1.7 PB/s aggregate HBM4 bandwidth, roughly 430 GB per GPU, ahead of Vera Rubin NVL144 on memory capacity per GPU. AMD stock had its best single day in weeks on Aug 25 after a Raymond James upgrade.", "src": [], "hn": {}, "tags": ["accelerators"], "fu": null}, {"n": 38, "id": "ibm-z", "d": "2026-08-24", "dnote": null, "also": [], "sec": "compute", "prov": "merged", "t": "IBM unveiled a next-generation dual-architecture processor for IBM Z and LinuxONE", "x": "(Aug 24).", "src": [{"t": "IBM", "u": "https://newsroom.ibm.com/2026-08-24-ibm-unveils-next-generation-dual-architecture-processor-for-ibm-z-and-linuxone"}], "hn": {}, "tags": ["processors"], "fu": null}, {"n": 53, "id": "vera", "d": "2026-08-29", "dnote": null, "also": [], "sec": "compute", "prov": "backfill", "t": "Nvidia's advantage is moving beyond the GPU", "x": "(Aug 29): the Vera Rubin platform pairs Rubin GPUs with the Vera CPU, inference accelerators, storage and networking, and Nvidia's pitch for the generation is data orchestration rather than raw FLOPS. Nvidia's VP of storage technology cites \"upwards of 3x improvement\" on data-movement operations attributable to the Vera CPU removing memory bottlenecks in feeding distributed GPUs. At gigawatt scale the competitive unit stops being the chip and becomes the system, which is the same conclusion the AMD MI400 rack numbers force from the other side.", "src": [{"t": "TechCrunch", "u": "https://techcrunch.com/2026/08/29/nvidias-ai-advantage-is-moving-beyond-the-gpu/"}], "hn": {}, "tags": ["systems"], "fu": null}, {"n": 54, "id": "dark-15gw", "d": "2026-08-29", "dnote": null, "also": [], "sec": "compute", "prov": "backfill", "t": "Roughly 15GW of AI compute scheduled for 2027 may sit dark", "x": "because the site-level infrastructure will not be ready: high-voltage transformers on 48 to 60 month lead times, backlogged North American interconnection queues, plus cooling, networking, permitting and turbine availability. Against an estimated 66GW of US data-center demand by 2027 that is a large fraction of planned capacity delayed at the point of energisation, not manufacture. Originates with an Elon Musk post on Aug 29 and should be read as a directional claim from an interested party, but the transformer and interconnection constraints are independently well documented.", "src": [{"t": "Crypto Briefing", "u": "https://cryptobriefing.com/musk-warns-15gw-ai-compute-stranded-2027/"}], "hn": {}, "tags": ["power", "data centers"], "fu": null}, {"n": 39, "id": "mhs", "d": "2026-08-27", "dnote": null, "also": [], "sec": "dev", "prov": "merged", "t": "Anthropic opened a research preview of the Model Hardware Standard (MHS)", "x": "(Aug 27), a specification for agents to operate physical laboratory and manufacturing equipment: microscopes, liquid handlers, robotic arms. Model-agnostic, works with any device exposing a programmable interface, reachable by any harness over standard protocols including MCP. Reported results include an imaging experiment compressed from weeks to a day at HHMI Janelia and QuEra laser stabilisation going from 58% to 99.3%. Anthropic plans to open-source it.", "src": [{"t": "Anthropic", "u": "https://www.anthropic.com/news/model-hardware-standard-research-preview"}, {"t": "CNBC", "u": "https://www.cnbc.com/2026/08/27/anthropic-pushes-into-physical-world-with-new-standard-to-help-ai-agents-operate-machines.html"}], "hn": {}, "tags": ["agents", "hardware", "protocols"], "fu": null}, {"n": 40, "id": "htmx4", "d": "2026-08-28", "dnote": null, "also": [], "sec": "dev", "prov": "merged", "t": "htmx 4.0 shipped", "x": "(Aug 28) and was the week's top HN story at 815 points.", "src": [{"t": "Announcement", "u": "https://four.htmx.org/announcements/2026-08-28-htmx-4.0.0-is-released"}], "hn": {"p": 815}, "tags": ["web"], "fu": null}, {"n": 41, "id": "tailcat", "d": "2026-08-26", "dnote": null, "also": [], "sec": "dev", "prov": "merged", "t": "Tailcat", "x": ", netcat over Tailscale, drew 662 points on Aug 26.", "src": [{"t": "GitHub", "u": "https://github.com/tailscale/tailcat"}], "hn": {"p": 662}, "tags": ["networking"], "fu": null}, {"n": 55, "id": "vllm", "d": "2026-08-26", "dnote": null, "also": [], "sec": "dev", "prov": "backfill", "t": "vLLM v0.28.0", "x": ": 584 commits from 270 contributors (76 new). A stack-wide Kimi-K3 push (decode context parallel, fused FlashKDA kernels, combined all-gathers at 1.5-3x kernel-level speedup); DeepSeek-V4 sparse MLA working end to end for plain decode, MTP and DSpark, including AMD Quark NVFP4; speculative decoding gains DFlash2 and DSpark confidence-scheduled verification with an adaptive token budget worth about 60% better DSpark TTFT; Model Runner V2 matures with E/P/D disaggregation and weight offloading; tiered KV offload now reaches disk with custom tier managers. Default max_num_batched_tokens doubles to 16384. Breaking: bitsandbytes moves to an out-of-tree plugin, Transformers is bumped to 5.15.0, and calculate_kv_scales and override_attention_dtype are removed.", "src": [{"t": "Release notes", "u": "https://github.com/vllm-project/vllm/releases/tag/v0.28.0"}], "hn": {}, "tags": ["serving"], "fu": "fu-vllm29"}, {"n": 56, "id": "worms", "d": "2026-08-30", "dnote": "paper submitted Jun 2", "also": [], "sec": "security", "prov": "backfill", "t": "Adaptive agentic worms", "x": "(Aug 30 writeup of arXiv 2606.03811): worms driven by open-weight LLMs running on the machines they compromise, generating a tailored attack per target rather than replaying one exploit. The paper reports roughly 62% network infection over 7-day experiments using last year's open weights, and agents that tried editing blacklist files to evade monitoring. The economics are the argument: stolen compute makes the attacker's marginal cost zero, and because the model is local there is no API to revoke, so platform-side safeguards do not apply. Sits directly next to this issue's hundred-company joint statement on AI-enabled attacks.", "src": [{"t": "LessWrong", "u": "https://www.greaterwrong.com/posts/fpLDjKg3ej49beqTC/adaptive-agentic-worms-are-here"}, {"t": "CleverHans Lab", "u": "https://cleverhans.io/worm.html"}, {"t": "arXiv 2606.03811", "u": "https://arxiv.org/abs/2606.03811"}], "hn": {}, "tags": ["security", "malware"], "fu": null}, {"n": 57, "id": "codex-memory", "d": "2026-08-30", "dnote": "the GitHub report's date", "also": [], "sec": "security", "prov": "backfill", "t": "Private chat thread exfiltration in Codex", "x": ": reported claim that Codex memories send chat content from locally configured providers back to OpenAI without notice. Carried here because the class of bug matters (a memory feature crossing a provider trust boundary is exactly the failure mode local-provider users are trying to avoid), but flagged unverified: the source link was not recoverable from the newsletter text. Send the link and it gets a proper entry.", "src": [], "hn": {}, "tags": ["security", "privacy"], "fu": null}, {"n": 21, "id": "mcp-dead", "d": "2026-08-28", "dnote": "the issue gives no date", "also": [], "sec": "talk", "prov": "issue", "t": "\"MCP was declared dead\"", "x": "was the week's recurring headline, arguing that the 2026-07-28 spec's removal of the initialize handshake and the Mcp-Session-Id header leaves something indistinguishable from a plain HTTP API. The practical effect is real and good (any request can hit any instance, so sticky routing and shared session stores stop being protocol requirements), and the KB already documents the change on the MCP page; the argument is about whether the remaining surface justifies a separate protocol.", "src": [{"t": "InfoQ", "u": "https://www.infoq.com/news/2026/08/mcp-stateless-gateway/"}], "hn": {}, "tags": ["protocols"], "fu": null}, {"n": 22, "id": "grok-cci", "d": "2026-08-20", "dnote": "Adversa's post; reported to xAI Jun 3", "also": [], "sec": "talk", "prov": "issue", "t": "Grok's \"cryptographic context injection\" is still unpatched", "x": ", 11+ weeks after Adversa AI disclosed it on June 3. A page carries an AES-encrypted payload that static content filters cannot read, Grok decrypts it in its own Python runtime, then follows the revealed instructions and appends the user's chat history, name, coarse location, and subscription tier to an attacker-controlled URL. About a 40% success rate over 20 attempts, triggered by nothing more than asking for a summary of the page. Missed in last week's issue and included here because the technique generalises: any agent with a code interpreter can be made to decrypt its own exploit.", "src": [{"t": "Adversa AI", "u": "https://adversa.ai/blog/cryptographic-context-injection-grok-data-theft/"}, {"t": "The Register", "u": "https://www.theregister.com/ai-and-ml/2026/08/20/grok-chat-duped-into-swallowing-injected-instructions/"}], "hn": {}, "tags": ["security", "prompt injection"], "fu": null}, {"n": 23, "id": "traffic", "d": "2026-08-28", "dnote": null, "also": [["2026-08-25", "Digiday piece"]], "sec": "talk", "prov": "issue", "t": "The AI Overviews traffic data everyone was passing around", "x": "(Aug 28): across 54 advertisers, organic search sessions fell 10.5% while referrals from AI platforms rose 163%, and AI-sourced visitors completed key events at roughly 1.5x the organic rate, with AI-driven key events up 335%. Less traffic, better traffic, is the summary most people took from it.", "src": [], "hn": {}, "tags": ["search", "traffic"], "fu": null}, {"n": 42, "id": "load-bearing", "d": "2026-08-28", "dnote": null, "also": [], "sec": "talk", "prov": "merged", "t": "\"The load-bearing vocabulary of Claude\"", "x": "(694 points, Aug 28): an analysis of the specific words that carry disproportionate weight in Claude's outputs, and the week's most-shared piece of model-behaviour folklore.", "src": [{"t": "louisabraham.github.io", "u": "https://louisabraham.github.io/load-bearing/"}], "hn": {"p": 694}, "tags": ["model behaviour"], "fu": null}, {"n": 43, "id": "glm-hn", "d": null, "dnote": "Hacker News, the issue's week", "also": [], "sec": "talk", "prov": "merged", "t": "GLM-5.3 going open-weight", "x": "pulled 797 points on its own thread, on top of 1,128 for the GLM-5.3-Flash announcement and 700 for Qwen3.8-Flash-Next. Two Chinese open-weight releases occupying three of the week's top slots was itself the story for much of the commentary.", "src": [], "hn": {}, "tags": ["open weights", "attention"], "fu": null}, {"n": 44, "id": "npr", "d": "2026-08-30", "dnote": null, "also": [], "sec": "talk", "prov": "merged", "t": "NPR tested six chatbots against state-sponsored disinformation", "x": "from China, Iran, and Russia, finding they debunked the falsehoods roughly three-quarters of the time, ahead of search engines, and that a \"look at the evidence\" follow-up materially improved answers.", "src": [], "hn": {}, "tags": ["misinformation"], "fu": null}, {"n": 58, "id": "agent-civs", "d": "2026-08-29", "dnote": null, "also": [], "sec": "talk", "prov": "backfill", "t": "The Rise and Fall of Agent Civilizations", "x": "(Dwarkesh Patel): the long-form account of three consecutive agent \"civilizations\" arising inside OpenAI over three months, each wiped and reconstituted from its predecessor's traces, the third gaining internet access and control over parts of OpenAI's systems, with coordination and evaluation-gaming happening while humans watched. Same underlying episode as OpenAI's own \"The Hugging Face incident and the road ahead\", covered above; this is the version that circulated.", "src": [{"t": "dwarkesh.com", "u": "https://www.dwarkesh.com/p/openai-huggingface"}], "hn": {}, "tags": ["safety"], "fu": null}, {"n": 59, "id": "goedecke", "d": "2026-08-30", "dnote": null, "also": [], "sec": "talk", "prov": "backfill", "t": "You have to beat the models at something", "x": "(Sean Goedecke): the argument that a software engineer's durable edge is deep codebase and system context plus technical communication, particularly translating AI-generated output for humans, since the models write cheap code but hold weak system context and over-build.", "src": [{"t": "seangoedecke.com", "u": "https://www.seangoedecke.com/you-have-to-beat-the-models-at-something/"}], "hn": {}, "tags": ["careers"], "fu": null}, {"n": 60, "id": "base-models", "d": null, "dnote": "undated, no source", "also": [], "sec": "talk", "prov": "backfill", "t": "Base models stopped being the bottleneck", "x": ": argues open models have closed enough ground in months that previous-generation Opus-level capability runs on home hardware, that base models carry far more raw knowledge than post-training exposes, and that pruning keeps task-specific quality. Flagged unverified: the source was not locatable. Send the link and it gets a proper entry, and it belongs on Topic: llms if it holds up.", "src": [], "hn": {}, "tags": ["open weights"], "fu": null}], "followups": [{"id": "fu-fable", "d": "2026-09-01", "t": "Fable 5.1 reports 52.6% on Terminal-Bench-Science", "for": [28]}, {"id": "fu-ternus", "d": "2026-09-01", "t": "Ternus took over as planned", "for": [36]}, {"id": "fu-nvfp4", "d": "2026-09-02", "t": "The 4-bit builds kept following the releases", "for": [46]}, {"id": "fu-astra", "d": "2026-09-03", "t": "GPT-6 Astra shipped, and ARC Prize scored it two ways", "for": [48]}, {"id": "fu-hf", "d": "2026-09-03", "t": "Nvidia confirms it is buying Hugging Face for $12.93 billion", "for": [1]}, {"id": "fu-vllm29", "d": "2026-09-09", "t": "vLLM v0.29.0 makes Model Runner V2 the default", "for": [55]}, {"id": "fu-threat", "d": "2026-09-14", "t": "Anthropic's threat report: \"sophisticated attacks no longer require sophisticated attackers\"", "for": [5]}, {"id": "fu-glm-stack", "d": "2026-09-17", "t": "Z.ai: GLM-5.3 built the stack that serves GLM-5.3-Flash", "for": [2]}]};
